#[allow(
    clippy::many_single_char_names,
    clippy::similar_names,
    reason = "names, parameters and lines follow the description: one per input and step"
)]
pub fn filter(a: P3, b: P3, c: P3, f: P3, s: i128, t: i128) -> Option<Sign> {
    let d_x = exact_f64(b.x) - exact_f64(a.x);
    let d_y = exact_f64(b.y) - exact_f64(a.y);
    let d_z = exact_f64(b.z) - exact_f64(a.z);
    let e_x = exact_f64(f.x) - exact_f64(c.x);
    let e_y = exact_f64(f.y) - exact_f64(c.y);
    let e_z = exact_f64(f.z) - exact_f64(c.z);
    let u_x_1 = d_y * e_z;
    let u_x_2 = d_z * e_y;
    let u_x = u_x_1 - u_x_2;
    let u_y_1 = d_z * e_x;
    let u_y_2 = d_x * e_z;
    let u_y = u_y_1 - u_y_2;
    let u_z_1 = d_x * e_y;
    let u_z_2 = d_y * e_x;
    let u_z = u_z_1 - u_z_2;
    let uu_1 = u_x * u_x;
    let uu_2 = u_y * u_y;
    let uu_3 = uu_1 + uu_2;
    let uu_4 = u_z * u_z;
    let uu = uu_3 + uu_4;
    let de_1 = d_x * e_x;
    let de_2 = d_y * e_y;
    let de_3 = de_1 + de_2;
    let de_4 = d_z * e_z;
    let de = de_3 + de_4;
    let t = rounded_f64(t, 40)?;
    let lead_1 = t * t;
    let lead_2 = lead_1 * uu;
    let s = rounded_f64(s, 40)?;
    let lead_3 = s * s;
    let lead_4 = lead_3 * de;
    let lead_5 = lead_4 * de;
    let lead = lead_2 - lead_5;
    let m_x = largest_magnitude([d_x, e_x]);
    let m_y = largest_magnitude([d_y, e_y]);
    let m_z = largest_magnitude([d_z, e_z]);
    let m_slope = largest_magnitude([t, s]);
    let scale = larger(m_z * m_z * m_z * m_z, m_y * m_y * m_z * m_z);
    let scale = larger(scale, m_y * m_y * m_y * m_y);
    let scale = larger(scale, m_x * m_x * m_z * m_z);
    let scale = larger(scale, m_x * m_x * m_y * m_y);
    let scale = larger(scale, m_x * m_x * m_x * m_x);
    let scale = m_slope * m_slope * scale;
    decide(lead, ERROR, scale)
}

/// `line_cone_lead`'s exact value: each step in the type its certificate gives it, with checked
